"""museum.js = imports + the shared render header (museum_head.js, from mlike.js) + parts/*.js in order. Run after editing a part."""
import os
D = os.path.dirname(os.path.abspath(__file__))
body = "\n".join(open(os.path.join(D, "parts", n)).read() for n in ["helpers.js", "gallery.js", "thief.js", "corridor.js", "tail.js"])
imports = '''// "The Mona Lisa": museum set (gallery | corridor | security), same render chain as The Mysterious Like (AgX, GTAO, ink lines, bokeh, bloom, grade)
// and the same character system (charlayer v2). GENERATED by build_museum.py from museum_head.js (shared header of mlike.js) + parts/*.js.
import * as THREE from "three";
import { EffectComposer } from "three/addons/postprocessing/EffectComposer.js";
import { RenderPass } from "three/addons/postprocessing/RenderPass.js";
import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";
import { OutputPass } from "three/addons/postprocessing/OutputPass.js";
import { ShaderPass } from "three/addons/postprocessing/ShaderPass.js";
import { GTAOPass } from "three/addons/postprocessing/GTAOPass.js";
import { BokehPass } from "three/addons/postprocessing/BokehPass.js";
import { RoundedBoxGeometry } from "three/addons/geometries/RoundedBoxGeometry.js";
import { RoomEnvironment } from "three/addons/environments/RoomEnvironment.js";
import { createChars } from "./charlayer.js";
import { LIGHT_PRESETS } from "./charpresets.js";

'''
open(os.path.join(D, "museum.js"), "w").write(imports + open(os.path.join(D, "museum_head.js")).read() + "\n" + body)
print("museum.js built")
